from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy


class MaxMaximalCocktailsCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data

        nodes_list = data['nodes']
        edges_list = data['edges']
        cnt_maximal_cocktails = data['cnt_maximal_cocktails']

        new_edge = self.find_next_edge(nodes_list, edges_list, cnt_maximal_cocktails)

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=new_edge, type='custom')]
        )

    def find_next_edge(self, nodes, edges, current_cnt):
        n = len(nodes)
        existing_edges = set(edges)

        for i in range(n):
            for j in range(i + 1, n):
                if (nodes[i], nodes[j]) not in existing_edges and (nodes[j], nodes[i]) not in existing_edges:
                    new_edges = edges + [(nodes[i], nodes[j])]
                    new_cnt = self.calculate_maximal_cocktails(nodes, new_edges)
                    if new_cnt >= current_cnt:
                        return (nodes[i], nodes[j])
        return None

    def calculate_maximal_cocktails(self, nodes, edges):
        from itertools import combinations
        from collections import defaultdict

        graph = defaultdict(set)
        for u, v in edges:
            graph[u].add(v)
            graph[v].add(u)

        def is_independent_set(nodes, subset):
            for u, v in combinations(subset, 2):
                if v in graph[u] or u in graph[v]:
                    return False
            return True

        max_cocktails = 0
        for r in range(len(nodes), 0, -1):
            for subset in combinations(nodes, r):
                if is_independent_set(nodes, subset):
                    max_cocktails += 1
                    break
        return max_cocktails

